        strip(B.p(GO_ROAD), F, e0, e1, 10, f => pth(f) ? f.wC - 1.35 : D.u(f) + he(f) - 0.7, f => pth(f) ? f.wC - 1.2 : D.u(f) + he(f) - 0.7, (s, f) => (pth(f) ? f.zC : D.z(f)) - 0.08, 0.5);
        continue;
