      const top = p.t === 'ap' ? z - 2.85 : z - 2.75, hcap = big ? 3.0 : 2.4, wcap = D.hwS(f) - 0.4, wcapN = D.hwN(f) - 0.4, cu = u0 + (wcapN - wcap)/2, cq = F.P(f, cu);
